package com.rwi.myrepublic.astri.internal;import com.rwi.myrepublic.astri.AstriConfig;import java.io.IOException;import java.net.URI;import java.net.http.HttpClient;import java.net.http.HttpRequest;import java.net.http.HttpResponse;import java.time.Duration;import java.util.Base64;public class BoqClient{private HttpClient client;private AstriConfig config;private String authHeader;public
BoqClient(){this.config=AstriConfig.getInstance();this.client=HttpClient.newBuilder().connectTimeout(Duration.ofMillis(config.getConnectionTimeout())).build();String credentials=config.getUsername()+ ":"+config.getPassword();this.authHeader= "Basic "+Base64.getEncoder().encodeToString(credentials.getBytes());}public String addBoqDrm(String infraType,String infraTypeCode,String vendorName,String subcontVendorName,String equipmentName,String description,Double quantityMaterial,Double
quantityService,String remarks,String phase,String area,String areaPlantCode,Double overridePriceMaterial,Double overridePriceService)throws IOException,InterruptedException{String baseUrl=config.getApiBaseUrl();String path;String codeFieldName;if(infraType!=null&&infraType.equalsIgnoreCase("subfeeder")){path= "/osp/cluster/boq/add/subfeeder";codeFieldName= "subfeeder_code";}else if(infraType!=null&&infraType.equalsIgnoreCase("feeder")){path= "/osp/cluster/boq/add/feeder";codeFieldName=
"feeder_code";}else{path= "/osp/cluster/boq/add";codeFieldName= "cluster_code";}String url=baseUrl+path;String jsonBody=buildJsonBody(codeFieldName,infraTypeCode,vendorName,subcontVendorName,equipmentName,description,quantityMaterial,quantityService,remarks,phase,area,areaPlantCode,overridePriceMaterial,overridePriceService);HttpRequest request=HttpRequest.newBuilder().uri(URI.create(url)).header("Authorization",authHeader).header("Content-Type",
"application/json").timeout(Duration.ofMillis(config.getRequestTimeout())).POST(HttpRequest.BodyPublishers.ofString(jsonBody)).build();HttpResponse<String>response=client.send(request,HttpResponse.BodyHandlers.ofString());return response.body();}private String buildJsonBody(String codeFieldName,String codeValue,String vendorName,String subcontVendorName,String equipmentName,String description,Double quantityMaterial,Double quantityService,String remarks,String phase,String area,String
areaPlantCode,Double overridePriceMaterial,Double overridePriceService){StringBuilder json=new StringBuilder();json.append("{");appendJsonField(json,codeFieldName,codeValue,true);appendJsonField(json, "vendor_name",vendorName,true);appendJsonField(json, "subcont_vendor_name",subcontVendorName,true);appendJsonField(json, "equipment_name",equipmentName,true);appendJsonField(json, "description",description,true);appendJsonField(json, "quantity_material",quantityMaterial,true);appendJsonField(json,
"quantity_service",quantityService,true);appendJsonField(json, "remarks",remarks,true);appendJsonField(json, "phase",phase,true);appendJsonField(json, "area",area,true);appendJsonField(json, "area_plant_code",areaPlantCode,true);appendJsonField(json, "override_price_material",overridePriceMaterial,true);appendJsonField(json, "override_price_service",overridePriceService,false);json.append("}");return json.toString();}private void appendJsonField(StringBuilder json,String fieldName,Object
value,boolean addComma){json.append("\"").append(fieldName).append("\":");if(value==null){json.append("null");}else if(value instanceof String){json.append("\"").append(escapeJson((String)value)).append("\"");}else if(value instanceof Integer){json.append(value);}else if(value instanceof Double){json.append(String.format("%.2f",(Double)value));}else{json.append("\"").append(escapeJson(value.toString())).append("\"");}if(addComma){json.append(",");}}private String escapeJson(String
str){if(str==null)return "";return str.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n").replace("\r", "\\r").replace("\t", "\\t");}public void close(){}}